Database range is truncated at 0x0809374A. Suggested end 0x080937EC after the shared epilogue and its two literal words. Compile #8 matched all 43 rows that the current range judges, including all branch targets out of that range. Its nominal score 7800 is entirely the continuation being counted as extra, so the saved best is misleading. In the continuation, the branch after testing count == 0 has inverted condition/layout and the loop loads actor+0x70 into r0 instead of r1. Exact-prefix C (uses the same declarations as best attempt):
u8 sub_080936F0(u8 *actor, u16 selector)
{
    u8 *candidate;
    u16 mode = selector;
    u32 first = actor[0x70];
    u8 *state = D_03004F50;
    u8 *remaining = (u8 *)(0x4A + (u32)state);
    u32 count;
    s32 difference = *remaining;

    difference = first - difference;
    actor[0x54] = difference;
    first = state[0x58];
    if (first == 0) {
        if (sub_080937EC(actor, &candidate) == 0)
            return sub_08096D94();
        if (!(selector & 0x8000)) {
            *(u8 **)&actor[0x78] = candidate;
            *(u8 **)&state[0x54] = candidate;
        }
    } else {
        if (sub_08096DB0(actor, &candidate) == 0)
            return sub_08096D94();

        if (!(mode & 0x8000)) {
            *(u8 **)&actor[0x78] = candidate;
            *(u8 **)&state[0x54] = candidate;
            count = (((u32)mode << 24) + 0xFF000000u) >> 24;
            if (count == 0)
                goto done;
        } else {
            count = *remaining;
        }

        do {
            u32 prior = count;
            count = ((vu8 *)actor)[0x70];
            count = (u8)(count - prior);
            candidate = (u8 *)(count * 0x124 + (u32)D_03002AB0);
            if (!(0x80 & candidate[0xF1]) && !(0x50 & candidate[0xF0]))
                goto done;
            count = (u8)(prior - 1);
        } while (count != 0);
        {
            u8 one = 1;
            u8 *battle = D_03004F50;
            battle[0x4A] = one;
        }
    }

done:
    return sub_08096D88(actor);
}

